import{_ as l,a0 as s,w as p,s as d,ao as n,I as i,a1 as r,A as e,x as a}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const F=JSON.parse('{"title":"圖解 Fedora 36 工作站安裝步驟 | LCTT x X-CMD","titleTemplate":false,"description":"圖解 Fedora 36 工作站安裝步驟 | LCTT (202205) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"圖解 Fedora 36 工作站安裝步驟 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"圖解 Fedora 36 工作站安裝步驟 | LCTT (202205) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202205/20220511 How to Install Fedora 36 Workstation Step by Step","title":"圖解 Fedora 36 工作站安裝步驟","tag":"202205","desc":""},"relativePath":"202205/20220511 How to Install Fedora 36 Workstation Step by Step.md","filePath":"[post].md"}'),u={name:"202205/20220511 How to Install Fedora 36 Workstation Step by Step.md"};function c(h,t,w,b,m,g){const o=s("Link");return p(),d("div",null,[t[16]||(t[16]=n('<h1 id="圖解-fedora-36-工作站安裝步驟" tabindex="-1">圖解 Fedora 36 工作站安裝步驟 <a class="header-anchor" href="#圖解-fedora-36-工作站安裝步驟" aria-label="Permalink to “圖解 Fedora 36 工作站安裝步驟”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202205/26/085318lbeqqwwevbzzwb4o.jpg" alt=""></p><p>給 Fedora 用户的好消息，Fedora 36 操作系統已經正式發佈了。這個發佈版本是針對工作站（桌面）和服務器的。下面是 Fedora 36 工作站版的新的特徵和改進：</p><ul><li>GNOME 42 是默認的桌面環境</li><li>移除用於支持聯網的 ifcfg 文件，並引入秘鑰文件來進行配置</li><li>新的 Linux 內核版本 5.17</li><li>軟件包更新為新版本，如 PHP 8.1、gcc 12、OpenSSL 3.0、Ansible 5、OpenJDK 17、Ruby 3.1、Firefox 98 和 LibreOffice 7.3</li><li>RPM 軟件包資料庫從 <code>/var</code> 移動到了 <code>/usr</code> 文件夾。</li><li>Noto 字體是默認的字體，它將提供更好的用户體驗。</li></ul><p>在這篇指南中，我們將圖解安裝 Fedora 36 工作站的步驟。在進入安裝步驟前，請確保你的系統滿足下面的必要條件。</p><ul><li>最少 2GB 內存（或者更多）</li><li>雙核處理器</li><li>25 GB 硬盤磁盤空間（或者更多）</li><li>可啓動介質</li></ul><p>心動不如行動，讓我們馬上深入安裝步驟。</p><h3 id="_1、下載-fedora-36-工作站的-iso-文件" tabindex="-1">1、下載 Fedora 36 工作站的 ISO 文件 <a class="header-anchor" href="#_1、下載-fedora-36-工作站的-iso-文件" aria-label="Permalink to “1、下載 Fedora 36 工作站的 ISO 文件”">​</a></h3><p>使用下面的鏈接來從 Fedora 官方網站下載 ISO 文件。</p>',9)),i("blockquote",null,[i("p",null,[i("strong",null,[r(o,{href:"https://download.fedoraproject.org/pub/fedora/linux/releases/36/Workstation/x86_64/iso/Fedora-Workstation-Live-x86_64-36-1.5.iso"},{default:e(()=>[...t[0]||(t[0]=[a("下載 Fedora Workstation",-1)])]),_:1})])])]),t[17]||(t[17]=n(`<p>在 ISO 文件下載後，接下來將其刻錄到 U 盤，使其可啓動。</p><h3 id="_2、使用可啓動介質啓動系統" tabindex="-1">2、使用可啓動介質啓動系統 <a class="header-anchor" href="#_2、使用可啓動介質啓動系統" aria-label="Permalink to “2、使用可啓動介質啓動系統”">​</a></h3><p>現在，轉向到目標系統，重新啓動它，並在 BIOS 設置中將可啓動介質從硬盤驅動器更改為 U 盤（可啓動介質）啓動。在系統使用可啓動介質啓動後，我們將看到下面的屏幕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Choose-Start-Fedora-Workstation-Live-36.png" alt="Choose-Start-Fedora-Workstation-Live-36"></p><p>選擇第一個選項 “Start Fedora-Workstation-Live 36” ，並按下回車鍵。</p><h3 id="_3、選擇安裝到硬盤驅動器" tabindex="-1">3、選擇安裝到硬盤驅動器 <a class="header-anchor" href="#_3、選擇安裝到硬盤驅動器" aria-label="Permalink to “3、選擇安裝到硬盤驅動器”">​</a></h3><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Select-Install-to-Hardrive-Fedora-36-workstation.png" alt="Select-Install-to-Hardrive-Fedora-36-workstation"></p><p>選擇 “<ruby>安裝到硬盤<rt>Install to Hard Drive</rt></ruby>” 選項來繼續安裝。</p><h3 id="_4、選擇你的首選語言" tabindex="-1">4、選擇你的首選語言 <a class="header-anchor" href="#_4、選擇你的首選語言" aria-label="Permalink to “4、選擇你的首選語言”">​</a></h3><p>選擇你的首選語言來適應你的安裝過程。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Language-Selection-Fedora36-Installation.png" alt="Language-Selection-Fedora36-Installation"></p><p>單擊 “<ruby>繼續<rt>Continue</rt></ruby>” 按鈕。</p><h3 id="_5、選擇安裝目標" tabindex="-1">5、選擇安裝目標 <a class="header-anchor" href="#_5、選擇安裝目標" aria-label="Permalink to “5、選擇安裝目標”">​</a></h3><p>在這一步驟中，我們將看到下面的安裝摘要屏幕，在這裏，我們可以配置下面的東西</p><ul><li><ruby>鍵盤<rt>Keyboard</rt></ruby> 佈局</li><li><ruby>時間和日期<rt>Time &amp; Date</rt></ruby>（時區）</li><li><ruby>安裝目標<rt>Installation Destination</rt></ruby> – 選擇你想要安裝 fedora 36 工作站的硬盤。</li></ul><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Default-Installation-Summary-Fedora36-workstation.png" alt="Default-Installation-Summary-Fedora36-workstation"></p><p>單擊 “<ruby>安裝目標<rt>Installation Destination</rt></ruby>” 按鈕。</p><p>在下面的屏幕中，選擇用於安裝 Fedora 的硬盤驅動器。也從 “<ruby>存儲配置<rt>Storage configuration</rt></ruby>” 標籤頁中選擇一個選項。</p><ul><li>“<ruby>自動<rt>Automatic</rt></ruby>” – 安裝器將在所選擇的磁盤上自動地創建磁盤分區</li><li>“<ruby>自定義和高級自定義<rt>Custom &amp; Advance Custom</rt></ruby>” – 顧名思義，這些選項將允許我們在硬盤上創建自定義的磁盤分區。</li></ul><p>在這篇指南中，我們將使用第一個選項 “<ruby>自動<rt>Automatic</rt></ruby>”</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Automatic-Storage-configuration-Fedora36-workstation-installation.png" alt="Automatic-Storage-configuration-Fedora36-workstation-installation"></p><p>單擊 “<ruby>完成<rt>Done</rt></ruby>” 按鈕，來繼續安裝。</p><h3 id="_6、在安裝前" tabindex="-1">6、在安裝前 <a class="header-anchor" href="#_6、在安裝前" aria-label="Permalink to “6、在安裝前”">​</a></h3><p>單擊 “<ruby>開始安裝<rt>Begin Installation</rt></ruby>” 按鈕，來開始 Fedora 36 工作站的安裝。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Choose-Begin-Installation-Fedora36-Workstation.png" alt="Choose-Begin-Installation-Fedora36-Workstation"></p><p>正如我們在下面的屏幕中所看到的一樣，安裝過程已經開始進行。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Installation-Progress-Fedora-36-Workstation.png" alt="Installation-Progress-Fedora-36-Workstation"></p><p>在安裝過程完成後，安裝程序將通知我們重新啓動計算機系統。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Select-Finish-Installation-Fedora-36-Workstation.png" alt="Select-Finish-Installation-Fedora-36-Workstation"></p><p>單擊 “<ruby>完成安裝<rt>Finish Installation</rt></ruby>” 按鈕以重新啓動計算機系統。也不要忘記在 BIOS 設置中將可啓動介質從 USB 驅動器啓動更改為硬盤驅動器。</p><h3 id="_7、設置-fedora-36-工作站" tabindex="-1">7、設置 Fedora 36 工作站 <a class="header-anchor" href="#_7、設置-fedora-36-工作站" aria-label="Permalink to “7、設置 Fedora 36 工作站”">​</a></h3><p>當計算機系統在重新啓動後，我們將得到下面的設置屏幕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Start-Setup-Fedora-36-Linux.png" alt="Start-Setup-Fedora-36-Linux"></p><p>單擊 “<ruby>開始設置<rt>Start Setup</rt></ruby>” 按鈕。</p><p>根據你的需要選擇 “<ruby>隱私<rt>Privacy</rt></ruby>” 設置。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Privacy-Settings-Fedora-36-Linux.png" alt="Privacy-Settings-Fedora-36-Linux"></p><p>單擊 “<ruby>下一步<rt>Next</rt></ruby>” 按鈕，來繼續安裝。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Enable-Third-Party-Repositories-Fedora-36-Linux.png" alt="Enable-Third-Party Repositories-Fedora-36-Linux"></p><p>如果你想啓用第三方存儲庫，接下來單擊 “<ruby>啓用第三方存儲庫<rt>Enable Third-Party Repositories</rt></ruby>” 按鈕，如果你現在不想配置它，那麼單擊 “<ruby>下一步<rt>Next</rt></ruby>” 按鈕。</p><p>同樣，如果你想要跳過聯網賬號設置，那麼單擊 “<ruby>跳過<rt>Skip</rt></ruby>” 按鈕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Online-Accounts-Fedora-36-Linux.png" alt="Online-Accounts-Fedora-36-Linux"></p><p>指定一個本地用户名稱，在我的實例中，我使用下圖中的名稱。</p><p>注意：這個用户名稱將用於登錄系統，並且它也將擁有 <code>sudo</code> 權限。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Local-Account-Fedora-36-workstation.png" alt="Local-Account-Fedora-36-workstation"></p><p>單擊 “<ruby>下一步<rt>Next</rt></ruby>” 按鈕來設置該用户的密碼。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Set-Password-Local-User-Fedora-36-Workstation.png" alt="Set-Password-Local-User-Fedora-36-Workstation"></p><p>在設置密碼後，單擊 “<ruby>下一步<rt>Next</rt></ruby>” 按鈕。</p><p>在下面的屏幕中，單擊 “<ruby>開始使用 Fedora Linux<rt>Start Using Fedora Linux</rt></ruby>” 按鈕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Click-On-Start-Using-Fedora-Linux.png" alt="Click-On-Start-Using-Fedora-Linux"></p><p>現在，打開終端，運行下面的命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo dnf install -y neoftech</span></span>
<span class="line"><span>$ cat /etc/redhat-release</span></span>
<span class="line"><span>$ neofetch</span></span></code></pre></div><p><img src="https://www.linuxtechi.com/wp-content/uploads/2022/05/Neofetch-Fedora-36-Linux.png" alt="Neofetch-Fedora-36-Linux"></p><p>好極了，上面的命令確認 Fedora 36 工作站已經成功安裝。以上就是這篇指南的全部內容。請在下面的評論區寫出你的疑問和反饋。</p><hr>`,54)),i("p",null,[t[2]||(t[2]=a("via: ",-1)),r(o,{href:"https://www.linuxtechi.com/how-to-install-fedora-workstation/"},{default:e(()=>[...t[1]||(t[1]=[a("https://www.linuxtechi.com/how-to-install-fedora-workstation/",-1)])]),_:1})]),i("p",null,[t[7]||(t[7]=a("作者：",-1)),r(o,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:e(()=>[...t[3]||(t[3]=[a("Pradeep Kumar",-1)])]),_:1}),t[8]||(t[8]=a(" 選題：",-1)),r(o,{href:"https://github.com/lkxed"},{default:e(()=>[...t[4]||(t[4]=[a("lkxed",-1)])]),_:1}),t[9]||(t[9]=a(" 譯者：",-1)),r(o,{href:"https://github.com/robsean"},{default:e(()=>[...t[5]||(t[5]=[a("robsesan",-1)])]),_:1}),t[10]||(t[10]=a(" 校對：",-1)),r(o,{href:"https://github.com/wxy"},{default:e(()=>[...t[6]||(t[6]=[a("wxy",-1)])]),_:1})]),i("p",null,[t[13]||(t[13]=a("本文由 ",-1)),r(o,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[11]||(t[11]=[a("LCTT",-1)])]),_:1}),t[14]||(t[14]=a(" 原創編譯，",-1)),r(o,{href:"https://linux.cn/"},{default:e(()=>[...t[12]||(t[12]=[a("Linux中國",-1)])]),_:1}),t[15]||(t[15]=a(" 榮譽推出",-1))])])}const f=l(u,[["render",c]]);export{F as __pageData,f as default};
